/**
 * PNG Icon Rasterizer
 *
 * Social-link scrapers (Open Graph / Twitter cards) and iOS home-screen icons
 * do not accept SVG, so this renders the project's existing maskable SVG
 * icons (generated by scripts/generate-icons.js) to PNG using the browser
 * already installed on the machine. No new dependencies.
 *
 * Run: node scripts/rasterize-icons.js
 * Optional: CHROME_PATH=/path/to/chrome-or-edge
 *
 * Outputs (committed, regenerate only when the icon artwork changes):
 *   public/icons/icon-maskable-512x512.png  — og:image / twitter:image
 *   public/icons/icon-maskable-192x192.png  — apple-touch-icon
 */

import fs from 'fs';
import os from 'os';
import path from 'path';
import { execFileSync } from 'child_process';
import { fileURLToPath, pathToFileURL } from 'url';

const here = path.dirname(fileURLToPath(import.meta.url));
const iconsDir = path.join(here, '../public/icons');

const TARGETS = [512, 192];

function findBrowser() {
  const candidates = [
    process.env.CHROME_PATH,
    'C:/Program Files/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
    '/usr/bin/google-chrome',
    '/usr/bin/chromium',
    '/usr/bin/chromium-browser',
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ].filter(Boolean);
  const found = candidates.find((candidate) => fs.existsSync(candidate));
  if (!found) {
    throw new Error('No Chrome/Edge found. Install one or set CHROME_PATH.');
  }
  return found;
}

const browser = findBrowser();
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'sscc-rasterize-'));

try {
  for (const size of TARGETS) {
    const svg = path.join(iconsDir, `icon-maskable-${size}x${size}.svg`);
    const png = path.join(iconsDir, `icon-maskable-${size}x${size}.png`);
    if (!fs.existsSync(svg)) throw new Error(`Missing ${svg}`);

    execFileSync(
      browser,
      [
        '--headless=new',
        '--disable-gpu',
        '--no-first-run',
        `--user-data-dir=${profile}`,
        `--window-size=${size},${size}`,
        '--hide-scrollbars',
        `--screenshot=${png}`,
        pathToFileURL(svg).href,
      ],
      { stdio: 'ignore', timeout: 60000 }
    );
    console.log(`wrote ${path.relative(process.cwd(), png)} (${fs.statSync(png).size} bytes)`);
  }
} finally {
  fs.rmSync(profile, { recursive: true, force: true });
}
